import {
  appendFileSync,
  closeSync,
  copyFileSync,
  existsSync,
  fsyncSync,
  mkdirSync,
  openSync,
  readFileSync,
  readdirSync,
  renameSync,
  unlinkSync,
  writeFileSync,
} from 'node:fs';
import { createHash } from 'node:crypto';
import { basename, dirname, join } from 'node:path';

export class LockHeldError extends Error {
  constructor(lockPath, ownerPid) {
    super(`LockHeld: ${lockPath} is held by pid ${ownerPid}`);
    this.name = 'LockHeldError';
  }
}

export class CasMismatchError extends Error {
  constructor(message) {
    super(`CasMismatch: ${message}`);
    this.name = 'CasMismatchError';
  }
}

export function acquireLock(targetPath) {
  const lockPath = `${targetPath}.lock`;
  const body = JSON.stringify({ pid: process.pid, utc: new Date().toISOString() });
  let fd;

  try {
    fd = openSync(lockPath, 'wx');
    writeFileSync(fd, body);
  } catch (error) {
    if (error?.code === 'EEXIST') {
      throw new LockHeldError(lockPath, lockOwnerPid(lockPath));
    }
    throw error;
  } finally {
    if (fd !== undefined) {
      closeSync(fd);
    }
  }

  let released = false;
  return () => {
    if (released) {
      return;
    }
    released = true;
    try {
      unlinkSync(lockPath);
    } catch (error) {
      if (error?.code !== 'ENOENT') {
        throw error;
      }
    }
  };
}

export function sha256(path) {
  return createHash('sha256').update(readFileSync(path)).digest('hex');
}

export function backupRotate(targetPath, keep = 5, ts = utcBasic(new Date())) {
  if (!existsSync(targetPath)) {
    return;
  }

  const dir = dirname(targetPath);
  const prefix = `${basename(targetPath)}.bak-`;
  copyFileSync(targetPath, join(dir, `${prefix}${ts}`));

  const backups = readdirSync(dir)
    .filter((name) => name.startsWith(prefix))
    .sort();

  for (const name of backups.slice(0, Math.max(0, backups.length - keep))) {
    unlinkSync(join(dir, name));
  }
}

export function commitCandidate(candidatePath, targetPath, expectedSha) {
  if (expectedSha === null) {
    if (existsSync(targetPath)) {
      throw new CasMismatchError(`${targetPath} target exists (expected first-append)`);
    }
  } else if (!existsSync(targetPath)) {
    throw new CasMismatchError(`${targetPath} target missing (expected sha ${expectedSha})`);
  } else {
    const actualSha = sha256(targetPath);
    if (actualSha !== expectedSha) {
      throw new CasMismatchError(`${targetPath} sha mismatch (expected ${expectedSha}, actual ${actualSha})`);
    }
  }

  fsyncFile(candidatePath);
  renameSync(candidatePath, targetPath);
}

export function appendJournal(journalPath, obj) {
  mkdirSync(dirname(journalPath), { recursive: true });
  appendFileSync(journalPath, `${JSON.stringify(obj)}\n`, 'utf8');
}

function lockOwnerPid(lockPath) {
  try {
    const body = JSON.parse(readFileSync(lockPath, 'utf8'));
    return body.pid ?? 'unknown';
  } catch {
    return 'unknown';
  }
}

function fsyncFile(path) {
  const fd = openSync(path, 'r');
  try {
    fsyncSync(fd);
  } finally {
    closeSync(fd);
  }
}

function utcBasic(date) {
  return date.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}Z$/, 'Z');
}
